// Particle fountain with pooled buffers — designed for hero backgrounds.
// All storage is preallocated Float32Arrays; stepFountain() never allocates.

import * as THREE from 'three';

/**
 * Deterministic seeded RNG (mulberry32). Small, fast, good enough for jitter.
 */
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Create a fountain emitting from the origin.
 *
 * @param {object} [opts]
 * @param {number} [opts.max=500]        Hard cap on simultaneous particles.
 * @param {number} [opts.ratePerSec]     Particles spawned per second.
 * @param {number} [opts.gravity=-9.8]   Downward acceleration on Y.
 * @param {number} [opts.speed]          Initial upward speed.
 * @param {number} [opts.lifeSec]        Seconds before a particle is recycled.
 * @returns {Fountain}
 */
export function createFountain({
  max = 500,
  ratePerSec,
  gravity = -9.8,
  speed,
  lifeSec,
} = {}) {
  // Pooled storage — allocated once, here. Never inside the update loop.
  const positions = new Float32Array(max * 3);
  const velocities = new Float32Array(max * 3);
  const ages = new Float32Array(max);

  // Slot bookkeeping: LIFO free-list of reusable indices + active flags.
  const free = new Int32Array(max);
  const active = new Uint8Array(max);
  let freeCount = max;
  for (let i = 0; i < max; i++) free[i] = max - 1 - i;

  const geometry = new THREE.BufferGeometry();
  const positionAttr = new THREE.BufferAttribute(positions, 3);
  geometry.setAttribute('position', positionAttr);
  const points = new THREE.Points(geometry);

  return {
    max,
    ratePerSec,
    gravity,
    speed,
    lifeSec,
    positions,
    velocities,
    ages,
    active,
    points,
    geometry,
    positionAttr,

    // internal state
    _free: free,
    _freeCount: freeCount === undefined ? 0 : max, // placeholder, fixed below
    _aliveCount: 0,
    _spawnDebt: 0,
    _rng: mulberry32(0x9e3779b9),
  };
}

/**
 * Advance the simulation by dt seconds.
 * Spawns ratePerSec * dt particles (fractional debt accumulates across steps),
 * integrates live particles, recycles expired ones back into the free pool.
 * Allocates nothing.
 */
export function stepFountain(f, dt) {
  // --- spawning -----------------------------------------------------------
  if (dt > 0 && f.ratePerSec !== undefined) {
    f._spawnDebt += f.ratePerSec * dt;
    let toSpawn = Math.floor(f._spawnDebt);
    f._spawnDebt -= toSpawn;
    if (toSpawn > f._freeCount) {
      toSpawn = f._freeCount; // pool exhausted: drop the excess this frame
      f._spawnDebt = 0;
    }
    for (let s = 0; s < toSpawn; s++) {
      const i = f._free[--f._freeCount];
      f.active[i] = 1;
      f._aliveCount++;
      const j = i * 3;
      f.positions[j] = 0;
      f.positions[j + 1] = 0;
      f.positions[j + 2] = 0;
      // Upward velocity with small deterministic jitter.
      f.velocities[j] = (f.speed ?? 1) * 0.15 * (f._rng() * 2 - 1);
      f.velocities[j + 1] =
        (f.speed ?? 1) * (0.9 + 0.2 * f._rng());
      f.velocities[j + 2] = (f.speed ?? 1) * 0.15 * (f._rng() * 2 - 1);
      f.ages[i] = 0;
    }
  }

  // --- integrate + recycle -----------------------------------------------
  const gdt = f.gravity * dt;
  for (let i = 0; i < f.max; i++) {
    if (!f.active[i]) continue;
    const j = i * 3;
    f.velocities[j + 1] += gdt;
    f.positions[j] += f.velocities[j] * dt;
    f.positions[j + 1] += f.velocities[j + 1] * dt;
    f.positions[j + 2] += f.velocities[j + 2] * dt;
    f.ages[i] += dt;
    if (f.ages[i] > f.lifeSec) {
      f.active[i] = 0;
      f._aliveCount--;
      f._free[f._freeCount++] = i;
    }
  }

  // Upload pooled buffer to the GPU in one shot (no reallocation).
  f.positionAttr.needsUpdate = true;
}

/** Number of currently live particles. */
export function aliveCount(f) {
  return f._aliveCount;
}

