import { describe, it, expect } from 'vitest';
import { createFountain, stepFountain, aliveCount } from '../src/fountain.js';

const EPS = 1e-9;

function simulate(f, seconds, dt) {
  let t = 0;
  while (t < seconds - EPS) {
    const step = Math.min(dt, seconds - t);
    stepFountain(f, step);
    t += step;
  }
}

describe('fountain', () => {
  it('spawns ~rate*dt particles: after 1s at rate 100 aliveCount is 100 within 2', () => {
    const f = createFountain({ max: 500, ratePerSec: 100, speed: 5, lifeSec: 10 });
    simulate(f, 1.0, 1 / 60);
    expect(Math.abs(aliveCount(f) - 100)).toBeLessThanOrEqual(2);
  });

  it('alive count never exceeds max after 30s at rate 100 with lifeSec 2', () => {
    const f = createFountain({ max: 500, ratePerSec: 100, speed: 8, lifeSec: 2 });
    const dt = 1 / 60;
    for (let s = 0; s < 30 * (1 / dt); s++) {
      stepFountain(f, dt);
      expect(aliveCount(f)).toBeLessThanOrEqual(500);
      expect(aliveCount(f)).toBeGreaterThanOrEqual(0);
    }
    // steady state should hover around rate * lifeSec = 200
    expect(Math.abs(aliveCount(f) - 200)).toBeLessThanOrEqual(5);
  });

  it('recycles slots: a freed index is reused by a later spawn', () => {
    const f = createFountain({ max: 10, ratePerSec: 1, speed: 3, lifeSec: 1 });
    const seenFirstRound = [];

    // Spawn exactly one particle.
    stepFountain(f, 1);
    expect(aliveCount(f)).toBe(1);
    seenFirstRound.push(firstActiveIndex(f));

    // Advance past its lifetime at zero spawn rate -> it is recycled.
    simulate(f, 1.5, 1 / 30);
    expect(aliveCount(f)).toBe(0);

    // The pool must hand back the same slot on the next spawn.
    stepFountain(f, 1);
    expect(aliveCount(f)).toBe(1);
    expect(firstActiveIndex(f)).toBe(seenFirstRound[0]);
  });

  it('with gravity, peak y exceeds y at death', () => {
    const f = createFountain({ max: 1, ratePerSec: 1, speed: 5, lifeSec: 2 });
    stepFountain(f, 1); // exactly one particle in slot 0
    const j = 0;

    let peakY = -Infinity;
    const dt = 1 / 120;
    while (f.active[0]) {
      stepFountain(f, Math.min(dt, remainingLife(f)));
      if (!f.active[0]) break;
      peakY = Math.max(peakY, f.positions[j + 1]);
    }

    const deathY = f.positions[j + 1];
    expect(Number.isFinite(peakY)).toBe(true);
    expect(peakY).toBeGreaterThan(deathY);
  });

  it('stepping with dt=0 changes nothing', () => {
    const f = createFountain({ max: 50, ratePerSec: 20, speed: 4, lifeSec: 5 });
    simulate(f, 0.5, 1 / 60); // build up some state

    const before = {
      alive: aliveCount(f),
      positions: Float32Array.from(f.positions),
      velocities: Float32Array.from(f.velocities),
      ages: Float32Array.from(f.ages),
      debt: f._spawnDebt,
    };

    stepFountain(f, 0);

    expect(aliveCount(f)).toBe(before.alive);
    expect(Array.from(f.positions)).toEqual(Array.from(before.positions));
    expect(Array.from(f.velocities)).toEqual(Array.from(before.velocities));
    expect(Array.from(f.ages)).toEqual(Array.from(before.ages));
    expect(f._spawnDebt).toBeCloseTo(before.debt, 12);
  });
});

function firstActiveIndex(f) {
  for (let i = 0; i < f.max; i++) if (f.active[i]) return i;
  return -1;
}

function remainingLife(f) {
  // smallest dt that cannot overshoot past the particle's death by much
  return 1 / 120;
}

